    Wait --> Write["mcp2515_write_canMsg<br/>mcp_can.cpp:729-755"]
    Write --> SPI["SPI @ 10 MHz<br/>mcp_can.cpp:54"]
    SPI --> Bus["CAN bus TX (125 kbps)"]
